# Generated by scripts/build-native-motion.py; review provenance in config/motion-native-v1.json.
"""Read-only exact-version adapter for additive numbered2–4 full productions."""

from backlot import motion_native_runtime as native
from pathlib import Path
from backlot import motion_native_replay_numbered_02_05_production as production


def prepare(template,request,*,workspace):
    production.require(Path(workspace).resolve()==production.ROOT,'请使用此安装所属工作区')
    production.require(template['template_id'] in production.SPECS and template['version']==production.VERSION,'未知完整制作精确版本')
    production.require(isinstance(request,dict) and not(set(request)-{'data','action_ids'}),'仅接受准备目录和完整动作顺序')
    expected=production.actions(template['template_id'])
    if 'action_ids' in request:production.require(request['action_ids']==expected,'不支持动作子集、重排或替换')
    if 'data' not in request:return {'status':'blocked','submitted':False,'blockers':['请先准备完整语音、真实ASR、同源人物与实拍输入'],'invocation':None}
    production.require(isinstance(request['data'],str) and request['data'].strip(),'data须为目录字符串')
    data=Path(request['data']);data=(data if data.is_absolute() else production.ROOT/data).resolve()
    episode,manifest,probes=production.validate(data)
    production.require(episode['template_id']==template['template_id'],'实际场景与所选精确模板不符')
    return {'status':'prepared','submitted':False,'blockers':[],'execution_status':'ready_for_queued_frames',
        'renderer':template['renderer'],'action_bindings':template['actions'],
        'props':{'episode':episode},'inputs':{'data':str(data),'episode_manifest':str(data/'preparation.json'),'renderer_input_file':str(data/'public/episode.json')},
        'consumer':{'entrypoint':'backlot.motion_replay_numbered_02_05_production:admit',
            'input':{'data':str(data),'phase':'frames'},'requires_existing_queue':True},
        'timeline':{'clock':{'fps':episode['fps'],'duration_frames':episode['durationFrames']},'actions':episode['actions'],'events':production.resolve_events(episode)},
        'reproduction':{'contract':production.CONTRACT,'phases':['frames','render'],'complete_audio':True,'no_new_paid_calls':True},
        'validation_scope':'当前完整输入/来源/语义时钟；实际画面、编码声音与连续听审分项验收'}
